namespace SodiumBindings.Tests;

public class KeyEncapsulationTests
{
    private static readonly byte[] Seed = Convert.FromHexString("ba265a8d45a392cc78b6d997a2ce4e55a1183dffc176baa17d732d0e3eb20dc7");

    private static readonly byte[] PublicKey = Convert.FromHexString(
        "");

    private static readonly byte[] SecretKey = Convert.FromHexString("ba265a8d45a392cc78b6d997a2ce4e55a1183dffc176baa17d732d0e3eb20dc7");

    private static readonly byte[] Ciphertext = Convert.FromHexString(
        "");

    private static readonly byte[] SharedSecret = Convert.FromHexString("84c04c3e124267415e8e825e201d3c601d67e81628caa97277dd404eac79a9c9");

    [Test]
    public async Task GenerateKeyPaid()
    {
        var publicKey = new byte[KeyEncapsulation.PublicKeyBytes];
        var secretKey = new byte[KeyEncapsulation.SecretKeyBytes];

        KeyEncapsulation.GenerateKeyPair(publicKey, secretKey);
    }

    [Test]
    public async Task GenerateKeyPairFromSeed()
    {
        var publicKey = new byte[KeyEncapsulation.PublicKeyBytes];
        var secretKey = new byte[KeyEncapsulation.SecretKeyBytes];

        KeyEncapsulation.GenerateKeyPairFromSeed(publicKey, secretKey, Seed);
        await Assert.That(publicKey.AsSpan().SequenceEqual(PublicKey)).IsTrue();
        await Assert.That(secretKey.AsSpan().SequenceEqual(SecretKey)).IsTrue();
    }

    [Test]
    public void Encrypt()
    {
        var ciphertext = new byte[KeyEncapsulation.CiphertextBytes];
        var sharedSecret = new byte[KeyEncapsulation.SharedSecretBytes];

        KeyEncapsulation.Encrypt(ciphertext, sharedSecret, PublicKey);
    }

    [Test]
    public async Task Decrypt()
    {
        var sharedSecret = new byte[KeyEncapsulation.SharedSecretBytes];

        KeyEncapsulation.Decrypt(sharedSecret, Ciphertext, SecretKey);

        await Assert.That(sharedSecret.AsSpan().SequenceEqual(SharedSecret)).IsTrue();
    }
}
